SELECT COUNT(*), SUM(CASE WHEN fare_amount IS NULL THEN NULL ELSE LEAST(GREATEST(fare_amount, 0), 20000) END), SUM(CASE WHEN trip_distance IS NULL THEN NULL ELSE LEAST(GREATEST(trip_distance, 0), 500) END) FROM (SELECT trip_id, hack_license, pu_location_id, fare_amount, trip_distance FROM (SELECT trip_id, hack_license, pu_location_id, fare_amount, trip_distance, ROW_NUMBER() OVER (PARTITION BY hack_license ORDER BY trip_id NULLS LAST) AS _rn FROM trips) AS _t WHERE _rn <= 50) AS trips
